const profileSlugs={'TCS London Marathon':'london-marathon','Skyline Scotland by UTMB':'skyline-scotland-utmb','Omagh Half Marathon & 5K':'omagh-half-marathon'};
const slugify=name=>races.find(r=>r.name===name)?.slug||profileSlugs[name]||name.toLowerCase().replace(/&/g,'and').replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'');
const card=r=>`<article class="card"><span class="tag">${r.type} · ${r.nation}</span><h3>${r.name}</h3><div class="meta">${r.distance} · ${r.place} · ${r.date}</div><p class="reason">${r.reason}</p><p class="unknown">Elevation: ${r.elevation}. Cut-off: ${r.cutoff}. Travel: ${r.transport}.</p><a href="/races/${slugify(r.name)}/">Profile ↗</a> <a href="${r.source}" target="_blank" rel="noreferrer">Official source ↗</a> <button class="compare" data-name="${r.name}">Add to compare</button></article>`;
function list(){const q=document.querySelector('#search').value.toLowerCase(),n=document.querySelector('#region').value,t=document.querySelector('#type').value;return races.filter(r=>(!q||(`${r.name} ${r.place}`).toLowerCase().includes(q))&&(n==='any'||r.nation===n)&&(t==='any'||r.type===t))};function render(){document.querySelector('#race-list').innerHTML=list().map(card).join('');bind()};let chosen=[];function bind(){document.querySelectorAll('.compare').forEach(b=>b.onclick=()=>{const r=races.find(x=>x.name===b.dataset.name);if(!chosen.includes(r)&&chosen.length<3)chosen.push(r);document.querySelector('#compare-panel').innerHTML=`<table class="compare-table"><tr><th>Detail</th>${chosen.map(x=>`<th>${x.name}</th>`).join('')}</tr>${[['Distance','distance'],['Elevation','elevation'],['Cut-off','cutoff'],['Transport','transport'],['Facilities','facilities']].map(f=>`<tr><th>${f[0]}</th>${chosen.map(x=>`<td>${x[f[1]]}</td>`).join('')}</tr>`).join('')}</table>`})};document.querySelector('#finder-form').onsubmit=e=>{e.preventDefault();const d=document.querySelector('#distance').value,s=document.querySelector('#surface').value;document.querySelector('#finder-results').innerHTML=races.filter(r=>(d==='any'||r.distance.toLowerCase().includes(d.toLowerCase())||(d==='Ultra'&&r.distance.includes('ultra')))&&(s==='any'||r.type===s)).slice(0,6).map(card).join('');bind()};['search','region','type'].forEach(id=>document.querySelector('#'+id).oninput=render);render();
const objectiveCopy={first:'Best read as a starting point for a first event when the published distance and facilities fit. Check current organiser instructions before entering.',pb:'This may suit a PB-focused runner where the surface is appropriate, but no pace or difficulty is inferred from missing data.',scenic:'A scenery-led possibility because the source identifies a trail, park or point-to-point setting. Elevation remains unknown where it is not published.',generous:'A generous time limit is only claimed when the source publishes one. Unknown cut-offs stay unknown.',carfree:'Travel information is available in part. A nearby station or shuttle does not prove race-day timing feasibility.'};
function profile(r){return `<div class="profile-backdrop" id="profile-view" role="dialog" aria-modal="true"><article class="profile"><button class="close-profile" aria-label="Close profile">×</button><span class="tag">${r.type} · ${r.nation}</span><h2>${r.name}</h2><p class="profile-sub">${r.distance} · ${r.place} · ${r.date} edition</p><p>${r.reason}</p><h3>What is verified</h3><dl><dt>Course / surface</dt><dd>${r.type==='road'?'Road course':'Trail or mixed course'}</dd><dt>Elevation</dt><dd>${r.elevation}</dd><dt>Cut-off</dt><dd>${r.cutoff}</dd><dt>Travel</dt><dd>${r.transport}</dd><dt>Facilities</dt><dd>${r.facilities}</dd></dl><p class="unknown">Unknown values are deliberately shown as unknown. This profile does not infer course difficulty, predicted finish time or public-transport feasibility.</p><a class="button dark" href="${r.source}" target="_blank" rel="noreferrer">Read official source ↗</a></article></div>`}
function showProfile(name){const r=races.find(x=>x.name===name);if(!r)return;document.querySelector('#profile-view')?.remove();document.body.insertAdjacentHTML('beforeend',profile(r));document.querySelector('.close-profile').onclick=()=>document.querySelector('#profile-view').remove();document.querySelector('#profile-view').onclick=e=>{if(e.target.id==='profile-view')e.target.remove()}}
const baseBind=bind;bind=function(){baseBind();document.querySelectorAll('.card').forEach(c=>{if(c.querySelector('.profile-button')||c.querySelector('.profile-link'))return;const b=document.createElement('button');b.className='profile-button';b.textContent='View profile';b.dataset.name=c.querySelector('h3').textContent;b.onclick=()=>showProfile(b.dataset.name);c.querySelector('.compare').before(b)});document.querySelectorAll('.compare').forEach(b=>b.textContent=chosen.some(x=>x.name===b.dataset.name)?'Added':'Add to compare')};
const originalSubmit=document.querySelector('#finder-form').onsubmit;document.querySelector('#finder-form').onsubmit=e=>{originalSubmit(e);const objective=document.querySelector('#objective').value;document.querySelectorAll('#finder-results .card').forEach(c=>{const r=races.find(x=>x.name===c.querySelector('h3').textContent);if(r){const p=document.createElement('p');p.className='objective-note';p.textContent=objectiveCopy[objective];c.querySelector('.reason').after(p)}})};
render();
/* User-journey P0: make evidence, uncertainty and next actions visible in the first result. */
const finderForm=document.querySelector('#finder-form');
if(!document.querySelector('#advanced-preferences')){const advanced=document.createElement('details');advanced.id='advanced-preferences';advanced.innerHTML='<summary>Refine your shortlist</summary><div class="advanced-grid"><label>Expected finish<select id="finish"><option value="any">Not sure yet</option><option value="beginner">First-time pace</option><option value="steady">Steady recreational pace</option><option value="fast">Faster / PB-focused</option></select></label><label>Travel preference<select id="travel"><option value="any">No preference</option><option value="carfree">Prefer rail, coach or shuttle information</option></select></label></div>';finderForm.insertBefore(advanced,finderForm.querySelector('button'))}
let richCard=r=>{const verified=[`Distance: ${r.distance}`,`Surface: ${r.type==='road'?'Road':'Trail / mixed'}`,r.elevation!=='Not confirmed'?`Elevation: ${r.elevation}`:null,r.cutoff!=='Not confirmed'?`Cut-off: ${r.cutoff}`:null,r.transport!=='Not confirmed'?`Travel: ${r.transport}`:null,r.facilities!=='Not confirmed'?`Facilities: ${r.facilities}`:null].filter(Boolean);const unknown=[r.elevation==='Not confirmed'?'Elevation':null,r.cutoff==='Not confirmed'?'Cut-off':null,r.transport==='Not confirmed'?'Travel timing':null,r.facilities==='Not confirmed'?'Facilities':null].filter(Boolean);const watch=unknown.length?`Check before entering: ${unknown.join(', ')} ${unknown.length===1?'is':'are'} not confirmed.`:'No major practical gaps were identified in the reviewed source.';return `<article class="card"><span class="tag">${r.type} · ${r.nation}</span><h3>${r.name}</h3><div class="meta">${r.distance} · ${r.place} · ${r.date}</div><p class="reason">${r.reason}</p><p class="confidence"><strong>Verified:</strong> ${verified.join(' · ')}</p><p class="watchouts"><strong>Watch out:</strong> ${watch}</p><div class="card-actions"><a class="profile-link" href="/races/${slugify(r.name)}/">Open full profile →</a><a href="${r.source}" target="_blank" rel="noreferrer">Official source ↗</a><button class="compare" data-name="${r.name}">Add to compare</button></div></article>`};
const textCard=richCard;richCard=r=>textCard(r).replace('<span class="tag">',r.image?`<img class="race-card-image" src="${r.image.src}" alt="${r.image.alt}" loading="lazy" width="480" height="218"><span class="tag">`:'<span class="tag">');
render=function(){document.querySelector('#race-list').innerHTML=list().map(richCard).join('');bind()};
finderForm.onsubmit=e=>{e.preventDefault();const d=document.querySelector('#distance').value,s=document.querySelector('#surface').value,o=document.querySelector('#objective').value,t=document.querySelector('#travel').value;let out=races.filter(r=>(d==='any'||r.distance.toLowerCase().includes(d.toLowerCase())||(d==='Ultra'&&r.distance.includes('ultra')))&&(s==='any'||r.type===s)&&(t!=='carfree'||r.transport!=='Not confirmed'));out=out.slice(0,6);document.querySelector('#finder-results').innerHTML=out.map(r=>richCard({...r,reason:`${r.reason} ${objectiveCopy[o]||''}`})).join('')||'<p class="empty">No races meet those verified filters yet. Try a broader preference or leave travel as no preference.</p>';bind()};
render();

const shortlistKey='race-fieldnotes-shortlist';let shortlist=[];try{shortlist=JSON.parse(sessionStorage.getItem(shortlistKey)||'[]')}catch(e){shortlist=[]}
function saveShortlist(){try{sessionStorage.setItem(shortlistKey,JSON.stringify(shortlist.map(r=>r.name)))}catch(e){}}
function shortlistPanel(){let p=document.querySelector('#shortlist-panel');if(!p){p=document.createElement('section');p.id='shortlist-panel';p.className='section shortlist-section';p.innerHTML='<div class="split"><div><p class="eyebrow">04 / Your shortlist</p><h2>Keep the useful options.</h2></div><p>This shortlist stays in this browser session. Nothing is sent to a server.</p></div><div id="shortlist-list" class="cards"></div>';document.querySelector('#compare').before(p)}return p}
function renderShortlist(){const p=shortlistPanel(),list=p.querySelector('#shortlist-list');list.innerHTML=shortlist.length?shortlist.map(r=>`<article class="card shortlist-card"><span class="tag">Saved option</span><h3>${r.name}</h3><div class="meta">${r.distance} · ${r.place}</div><p>${r.reason}</p><a class="profile-link" href="/races/${slugify(r.name)}/">Open profile →</a> <button class="remove-save" data-name="${r.name}">Remove</button></article>`).join(''):'<p class="empty">Save up to six races from the directory or finder to compare them later.</p>';list.querySelectorAll('.remove-save').forEach(b=>b.onclick=()=>{shortlist=shortlist.filter(r=>r.name!==b.dataset.name);saveShortlist();renderShortlist()})}
function renderJourneyCompare(){const p=document.querySelector('#compare-panel');if(!chosen.length){p.innerHTML='<p>Select races using “Add to compare”.</p>';return}const unknown=chosen.filter(r=>r.cutoff==='Not confirmed').map(r=>r.name),travel=chosen.filter(r=>r.transport!=='Not confirmed').map(r=>r.name);p.innerHTML=`<div class="compare-heading"><p>${chosen.length}/3 selected</p><button class="clear-compare">Clear comparison</button></div><table class="compare-table"><tr><th>Detail</th>${chosen.map(x=>`<th>${x.name}<button class="remove-compare" data-name="${x.name}">×</button></th>`).join('')}</tr>${[['Distance','distance'],['Elevation','elevation'],['Cut-off','cutoff'],['Transport','transport'],['Facilities','facilities']].map(f=>`<tr><th>${f[0]}</th>${chosen.map(x=>`<td>${x[f[1]]}</td>`).join('')}</tr>`).join('')}</table><div class="comparison-summary"><strong>How to read this:</strong> ${travel.length?`${travel.join(', ')} ${travel.length===1?'has':'have'} some travel information.`:'No selected race has confirmed travel information.'} ${unknown.length?`${unknown.join(', ')} ${unknown.length===1?'has':'have'} no confirmed cut-off.`:'Every selected race has a reviewed cut-off field.'}</div>`;p.querySelector('.clear-compare').onclick=()=>{chosen=[];renderJourneyCompare()};p.querySelectorAll('.remove-compare').forEach(b=>b.onclick=()=>{chosen=chosen.filter(x=>x.name!==b.dataset.name);renderJourneyCompare()})}
const journeyBind=bind;bind=function(){journeyBind();document.querySelectorAll('.card').forEach(c=>{if(c.querySelector('.save-race'))return;const b=document.createElement('button');b.className='save-race';const name=c.querySelector('h3').textContent;b.dataset.name=name;b.textContent=shortlist.some(x=>x.name===name)?'Saved':'Save';b.onclick=()=>{const r=races.find(x=>x.name===name);if(!r)return;if(shortlist.some(x=>x.name===name))shortlist=shortlist.filter(x=>x.name!==name);else if(shortlist.length<6)shortlist.push(r);saveShortlist();renderShortlist();bind()};const compare=c.querySelector('.compare');if(compare)compare.before(b)});document.querySelectorAll('.compare').forEach(b=>b.onclick=()=>{const r=races.find(x=>x.name===b.dataset.name);if(r&&!chosen.some(x=>x.name===r.name)&&chosen.length<3)chosen.push(r);renderJourneyCompare()})};
renderShortlist();render();
['search','region','type'].forEach(id=>document.querySelector('#'+id).oninput=render);
const hero=document.querySelector('.hero');if(hero&&!document.querySelector('#quick-search')){hero.insertAdjacentHTML('beforeend','<div class="quick-search"><label for="quick-search">Search the race guide</label><div><input id="quick-search" type="search" placeholder="Race name, town or region"><button class="button accent" id="quick-search-button">Search →</button></div></div>');document.querySelector('#quick-search').oninput=e=>{document.querySelector('#search').value=e.target.value;render()};document.querySelector('#quick-search-button').onclick=()=>document.querySelector('#directory').scrollIntoView({behavior:'smooth'})}
const directorySearch=document.querySelector('#search');if(directorySearch&&!document.querySelector('#directory-search-button')){directorySearch.insertAdjacentHTML('afterend','<button class="directory-search-button button accent" id="directory-search-button">Search →</button>');document.querySelector('#directory-search-button').onclick=()=>{render();document.querySelector('#race-list').scrollIntoView({behavior:'smooth',block:'start'})}}
const confirmedDates={'South Downs Way 50':['10 April 2027','April'],'Maverick Peak District X-Trail':['5 June 2027','June'],'Race to the Stones':['10–11 July 2027','July'],'Richmond Park Half Marathon':['15 August 2027','August'],'Great North Run':['12 September 2027','September'],'Alloa Half Marathon':['21 March 2027','March'],'Loch Ness Marathon':['26 September 2027','September'],'Inverness Half Marathon':['14 March 2027','March'],'TCS London Marathon':['24–25 April 2027','April'],'Omagh Half Marathon & 5K':['4 April 2027','April'],'Devil o the Highlands Footrace':['24 April 2027','April']};races.forEach(r=>{const d=confirmedDates[r.name];r.date=d?d[0]:(r.date||'2027 date not confirmed');r.dateMonth=d?d[1]:(r.dateMonth||'unknown')});
const baseListWithDates=list;list=function(){const rows=baseListWithDates();const m=document.querySelector('#date-filter')?.value||'any';return m==='any'?rows:rows.filter(r=>r.dateMonth===m)};
const typeFilter=document.querySelector('#type');if(typeFilter&&!document.querySelector('#date-filter'))typeFilter.insertAdjacentHTML('afterend','<select id="date-filter" aria-label="Filter by confirmed race month"><option value="any">Any date</option><option value="January">January 2027</option><option value="February">February 2027</option><option value="March">March 2027</option><option value="April">April 2027</option><option value="May">May 2027</option><option value="June">June 2027</option><option value="July">July 2027</option><option value="August">August 2027</option><option value="September">September 2027</option><option value="October">October 2027</option><option value="November">November 2027</option><option value="December">December 2027</option><option value="unknown">2027 date to confirm</option></select>');document.querySelector('#date-filter')?.addEventListener('change',render);render();


